import * as NodeRuntime from "@effect/platform-node/NodeRuntime"
import * as NodeServices from "@effect/platform-node/NodeServices"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as CliConfig from "effect/cli/CliConfig"
import * as Argument from "effect/cli/Argument"
import * as Command from "effect/cli/Command"
import * as Flag from "effect/cli/Flag"
import * as GlobalFlag from "effect/cli/GlobalFlag"
import * as IconGenerator from "./IconGenerator.ts"

const icons = Argument.String("icon").pipe(
  Argument.variadic({ min: 1 }),
  Argument.withDescription("Icon IDs such as fa7-brands:github"),
)

const output = Flag.Directory("output").pipe(
  Flag.withDefault("."),
  Flag.withDescription("Directory that receives generated icon collections"),
)

const generateCommand = Command.make("generate", { icons, output }).pipe(
  Command.withDescription("Generate static SVG files from Iconify collections"),
  Command.withHandler(({ icons, output }) =>
    IconGenerator.generate(icons, output),
  ),
)

export const command = Command.make("icon-generator").pipe(
  Command.withDescription("Generate Worker-safe static icon assets"),
  Command.withSubcommands([generateCommand]),
)

const program = Command.run(command, { version: "0.0.0" })

const MainLayer = Layer.mergeAll(
  CliConfig.layer({ builtIns: [GlobalFlag.Help] }),
  NodeServices.layer,
)

program.pipe(Effect.provide(MainLayer), NodeRuntime.runMain)

#!/usr/bin/env node

import * as NodeCrypto from "@effect/platform-node/NodeCrypto"
import * as NodeRuntime from "@effect/platform-node/NodeRuntime"
import * as NodeServices from "@effect/platform-node/NodeServices"
import * as Config from "effect/Config"
import * as Console from "effect/Console"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Option from "effect/Option"
import * as CliConfig from "effect/cli/CliConfig"
import * as Command from "effect/cli/Command"
import * as Flag from "effect/cli/Flag"
import * as GlobalFlag from "effect/cli/GlobalFlag"
import { InvalidStoreError } from "./Error.ts"
import { Mixedbread } from "./Mixedbread.ts"
import * as Preview from "./Preview.ts"
import { SearchChanges } from "./SearchChanges.ts"

const pullRequest = Flag.Int("pr").pipe(
  Flag.withDescription("Pull request number that identifies the preview store"),
)

const revision = Flag.String("sha").pipe(
  Flag.withDescription("Git commit SHA associated with the indexed content"),
)

const scope = Flag.Literals("scope", ["all", "markdown", "api-reference"]).pipe(
  Flag.withDefault("all"),
  Flag.withDescription("Content scope to synchronize"),
)

const base = Flag.String("base").pipe(
  Flag.withDescription("Base Git revision to compare"),
)

const head = Flag.String("head").pipe(
  Flag.withDescription("Head Git revision to compare"),
)

const syncCommand = Command.make("sync", {
  pullRequest: Flag.optional(pullRequest),
  revision,
  scope,
}).pipe(
  Command.withDescription(
    "Synchronize a Mixedbread documentation search store",
  ),
  Command.withHandler(({ pullRequest, revision, scope }) =>
    Option.match(pullRequest, {
      onNone: () =>
        Mixedbread.use((mixedbread) =>
          mixedbread.syncProduction(revision, scope),
        ),
      onSome: Effect.fnUntraced(function* (pullRequest) {
        if (scope !== "all") {
          return yield* new InvalidStoreError({
            message: `A preview synchronizes all content; --scope ${scope} is for production`,
          })
        }
        const storeId = yield* Config.String("MXBAI_VECTOR_STORE_ID")
        return yield* Mixedbread.use((mixedbread) =>
          mixedbread.syncPreview({
            kind: "preview",
            pullRequest,
            revision,
            storeId,
          }),
        )
      }),
    }),
  ),
  Command.provide(Mixedbread.layer),
)

const deleteCommand = Command.make("delete-preview", {
  pullRequest,
}).pipe(
  Command.withDescription("Delete a pull request's Mixedbread preview store"),
  Command.withHandler(({ pullRequest }) =>
    Mixedbread.use((mixedbread) => mixedbread.deleteStore({ pullRequest })),
  ),
  Command.provide(Mixedbread.layer),
)

const searchChangesCommand = Command.make("search-changes", {
  base,
  head,
}).pipe(
  Command.withDescription(
    "Detect whether a Git diff changes the Mixedbread search index",
  ),
  Command.withHandler(({ base, head }) =>
    SearchChanges.use((searchChanges) =>
      searchChanges.between(base, head),
    ).pipe(Effect.flatMap((changed) => Console.log(String(changed)))),
  ),
  Command.provide(SearchChanges.layer),
)

const previewStageCommand = Command.make("preview-stage", {
  pullRequest,
}).pipe(
  Command.withDescription("Compute a validated Alchemy preview stage"),
  Command.withHandler(({ pullRequest }) =>
    Preview.stage(pullRequest).pipe(Effect.flatMap(Console.log)),
  ),
)

const indexCommand = Command.make("mixedbread").pipe(
  Command.withDescription("Manage Mixedbread documentation search stores"),
  Command.withSubcommands([
    syncCommand,
    deleteCommand,
    searchChangesCommand,
    previewStageCommand,
  ]),
)

const program = Command.run(indexCommand, { version: "0.0.0" })

const MainLayer = Layer.mergeAll(
  CliConfig.layer({ builtIns: [GlobalFlag.Help] }),
  NodeServices.layer,
  NodeCrypto.layer,
)

program.pipe(Effect.provide(MainLayer), NodeRuntime.runMain)

import * as Duration from "effect/Duration"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Option from "effect/Option"
import * as Redacted from "effect/Redacted"
import * as Headers from "effect/http/Headers"
import * as HttpRouter from "effect/http/HttpRouter"
import * as HttpServerRequest from "effect/http/HttpServerRequest"
import * as HttpServerResponse from "effect/http/HttpServerResponse"
import * as HttpApiBuilder from "effect/http-api/HttpApiBuilder"
import {
  CurrentVoter,
  MotwVoteApi,
  VoteRateLimit,
  VoterIdentity,
  voterCookie,
} from "./api"
import { ModuleCatalog } from "./catalog"
import { VoteRefusedError } from "./domain"
import { ClientRateLimit, SecureCookie, Turnstile, VoterSigner } from "./guards"
import { VoteStore } from "./vote-store"

const VoteRateLimitLive = Layer.effect(
  VoteRateLimit,
  Effect.gen(function* () {
    const rateLimit = yield* ClientRateLimit
    return (httpEffect) =>
      Effect.gen(function* () {
        const request = yield* HttpServerRequest.HttpServerRequest
        const key = Headers.get(request.headers, "cf-connecting-ip").pipe(
          Option.getOrElse(() => "unknown"),
        )
        if (!(yield* rateLimit.allow(key))) {
          return yield* new VoteRefusedError({ reason: "RateLimited" })
        }
        return yield* httpEffect
      })
  }),
)

const VoterIdentityLive = Layer.effect(
  VoterIdentity,
  Effect.gen(function* () {
    const signer = yield* VoterSigner
    return {
      voter: Effect.fnUntraced(function* (httpEffect, { credential }) {
        const voter = yield* signer.verify(Redacted.value(credential))
        return yield* Effect.provideService(httpEffect, CurrentVoter, voter)
      }),
    }
  }),
)

const MotwVoteHandlers = HttpApiBuilder.group(
  MotwVoteApi,
  "motwVote",
  Effect.fnUntraced(function* (handlers) {
    const store = yield* VoteStore
    const catalog = yield* ModuleCatalog
    const turnstile = yield* Turnstile
    const signer = yield* VoterSigner
    const secure = yield* SecureCookie

    const isVotable = (id: string) =>
      Effect.map(catalog.status(id), (status) => status === "votable")

    const issueVoter = Effect.gen(function* () {
      const { id, token } = yield* signer.issue
      yield* HttpApiBuilder.securitySetCookie(voterCookie, token, {
        path: "/api/motw-vote",
        sameSite: "lax",
        secure,
        maxAge: Duration.days(365),
      })
      return id
    })

    return handlers
      .handle(
        "ranking",
        Effect.fn("MotwVote.ranking")(function* () {
          const voter = yield* CurrentVoter
          const [requests, voted] = yield* Effect.all(
            [
              store.top,
              Option.match(voter, {
                onNone: () => Effect.succeed([]),
                onSome: store.votedBy,
              }),
            ],
            { concurrency: "unbounded" },
          )
          return {
            requests: yield* Effect.filter(requests, ({ id }) => isVotable(id)),
            voted: yield* Effect.filter(voted, isVotable),
            turnstileSiteKey: turnstile.siteKey,
          }
        }),
      )
      .handle(
        "vote",
        Effect.fn("MotwVote.vote")(function* ({ payload }) {
          const status = yield* catalog.status(payload.id)
          if (status !== "votable") {
            return yield* new VoteRefusedError({
              reason: status === "covered" ? "Covered" : "UnknownModule",
            })
          }
          if (!(yield* turnstile.verify(payload.token))) {
            return yield* new VoteRefusedError({ reason: "ChallengeFailed" })
          }
          const known = yield* CurrentVoter
          const voter = Option.isSome(known) ? known.value : yield* issueVoter
          return yield* store.add(voter, payload.id)
        }),
      )
      .handle(
        "unvote",
        Effect.fn("MotwVote.unvote")(function* ({ payload }) {
          const voter = yield* CurrentVoter
          return yield* Option.match(voter, {
            onNone: () =>
              Effect.map(store.count(payload.id), (votes) => ({
                id: payload.id,
                votes,
                voted: false,
              })),
            onSome: (voterId) => store.remove(voterId, payload.id),
          })
        }),
      )
  }),
)

// Every response depends on the voter
const NoStore = HttpRouter.middleware(
  (httpEffect) =>
    Effect.map(
      httpEffect,
      HttpServerResponse.setHeader("cache-control", "private, no-store"),
    ),
  { global: true },
)

export const MotwVoteLive = Layer.mergeAll(
  HttpApiBuilder.layer(MotwVoteApi).pipe(
    Layer.provide(
      MotwVoteHandlers.pipe(
        Layer.provide([VoterIdentityLive, VoteRateLimitLive]),
      ),
    ),
  ),
  NoStore,
).pipe(Layer.provide(VoterSigner.layer))

import * as NodeFileSystem from "@effect/platform-node/NodeFileSystem"
import * as Data from "effect/Data"
import * as Effect from "effect/Effect"
import * as FileSystem from "effect/FileSystem"
import * as Schema from "effect/Schema"
import { createHash } from "node:crypto"
import { fileURLToPath } from "node:url"
import { parse } from "devalue"
import type { Plugin } from "vite"

const moduleId = "virtual:open-graph-metadata"
const resolvedModuleId = `\0${moduleId}`

const rendererVersionModuleId = "virtual:open-graph-renderer-version"
const resolvedRendererVersionModuleId = `\0${rendererVersionModuleId}`

const repositoryRoot = new URL("../../../../../", import.meta.url)

/**
 * Everything besides a page's own metadata that decides how its Open Graph
 * image looks: the renderer, its background assets, and (through the lockfile)
 * the Satori and resvg versions. Pages key the image URL on a digest of these
 * instead of the deploy revision, so an unchanged page renders byte-identical
 * HTML across commits and the incremental build can reuse it.
 */
const RENDERER_INPUTS = [
  "apps/web/src/features/open-graph",
  "apps/web/src/assets/og",
  "packages/open-graph/src",
  "pnpm-lock.yaml",
]

class OpenGraphMetadataPluginError extends Data.TaggedError(
  "OpenGraphMetadataPluginError",
)<{
  readonly detail: string
  readonly cause: unknown
}> {
  override get message(): string {
    return this.detail
  }
}

const ContentStore = Schema.ReadonlyMap(Schema.String, Schema.Unknown)

const DocsCollection = Schema.ReadonlyMap(
  Schema.String,
  Schema.Struct({
    id: Schema.String,
    data: Schema.Struct({ title: Schema.String }),
  }),
)

const BlogCollection = Schema.ReadonlyMap(
  Schema.String,
  Schema.Struct({
    id: Schema.String,
    data: Schema.Struct({
      title: Schema.String,
      excerpt: Schema.String,
      tags: Schema.Array(Schema.Struct({ id: Schema.String })),
    }),
  }),
)

const BlogTagsCollection = Schema.ReadonlyMap(
  Schema.String,
  Schema.Struct({
    id: Schema.String,
    data: Schema.Struct({ name: Schema.String }),
  }),
)

const ApiReferenceCollection = Schema.ReadonlyMap(
  Schema.String,
  Schema.Struct({
    id: Schema.String,
    data: Schema.Struct({
      version: Schema.String,
      packageSlug: Schema.String,
      packageName: Schema.String,
      modulePath: Schema.String,
    }),
  }),
)

const decodeCollection = <S extends Schema.Top>(
  store: ReadonlyMap<string, unknown>,
  collection: string,
  schema: S,
) =>
  Schema.decodeUnknownEffect(schema)(store.get(collection)).pipe(
    Effect.mapError(
      (cause) =>
        new OpenGraphMetadataPluginError({
          detail: `Astro content store contains invalid ${collection} metadata`,
          cause,
        }),
    ),
  )

const readCategory = (entryId: string): string | undefined => {
  const segments = entryId.split("/")
  return segments.length >= 3
    ? segments[1]?.replace(/-/g, " ").toUpperCase()
    : undefined
}

const loadMetadata = Effect.fn("OpenGraphMetadataPlugin.loadMetadata")(
  function* (storePath: string) {
    const fs = yield* FileSystem.FileSystem
    const serialized = yield* fs.readFileString(storePath).pipe(
      Effect.mapError(
        (cause) =>
          new OpenGraphMetadataPluginError({
            detail: `Unable to read Astro content store at ${storePath}`,
            cause,
          }),
      ),
    )
    const parsed: unknown = yield* Effect.try({
      try: () => parse(serialized),
      catch: (cause) =>
        new OpenGraphMetadataPluginError({
          detail: `Unable to parse Astro content store at ${storePath}`,
          cause,
        }),
    })
    const store = yield* Schema.decodeUnknownEffect(ContentStore)(parsed).pipe(
      Effect.mapError(
        (cause) =>
          new OpenGraphMetadataPluginError({
            detail: "Astro content store is not a map",
            cause,
          }),
      ),
    )
    const docsEntries = yield* decodeCollection(store, "docs", DocsCollection)
    const blogEntries = yield* decodeCollection(store, "blog", BlogCollection)
    const blogTagEntries = yield* decodeCollection(
      store,
      "blogTags",
      BlogTagsCollection,
    )
    const apiReferenceEntries = yield* decodeCollection(
      store,
      "apiReference",
      ApiReferenceCollection,
    )

    const docs = Object.fromEntries(
      Array.from(docsEntries.values(), (entry) => [
        entry.id,
        {
          title: entry.data.title,
          subtitle: readCategory(entry.id),
        },
      ]),
    )
    const tagNames = new Map(
      Array.from(blogTagEntries.values(), (tag) => [tag.id, tag.data.name]),
    )
    const blog = Object.fromEntries(
      Array.from(blogEntries.values(), (entry) => [
        entry.id,
        {
          title: entry.data.title,
          subtitle: entry.data.excerpt,
          tags: entry.data.tags
            .map((tag) => tagNames.get(tag.id) ?? tag.id)
            .sort((a, b) => a.localeCompare(b)),
        },
      ]),
    )
    const apiReference = Object.fromEntries(
      Array.from(apiReferenceEntries.values()).flatMap((entry) => {
        const { modulePath, packageName, packageSlug, version } = entry.data
        const moduleName = modulePath.split("/").at(-1) ?? modulePath
        return [
          [
            `${version}/api`,
            { eyebrow: "Effect Docs", title: "API Reference" },
          ],
          [
            `${version}/api/${packageSlug}`,
            { eyebrow: "API Reference", title: packageName },
          ],
          [
            `${version}/api/${packageSlug}/${modulePath}`,
            { eyebrow: "API Reference", title: moduleName },
          ],
        ]
      }),
    )

    return `export default ${JSON.stringify({ apiReference, blog, docs })}`
  },
)

const listFiles = Effect.fn("OpenGraphMetadataPlugin.listFiles")(function* (
  path: string,
) {
  const fs = yield* FileSystem.FileSystem
  const info = yield* fs.stat(path)
  if (info.type !== "Directory") return [path]
  const entries = yield* fs.readDirectory(path, { recursive: true })
  return yield* Effect.filter(
    entries.map((entry) => `${path}/${entry}`),
    (file) => fs.stat(file).pipe(Effect.map((stat) => stat.type === "File")),
  )
})

const loadRendererVersion = Effect.fn(
  "OpenGraphMetadataPlugin.loadRendererVersion",
)(function* () {
  const fs = yield* FileSystem.FileSystem
  const root = fileURLToPath(repositoryRoot)
  const files = yield* Effect.forEach(RENDERER_INPUTS, (input) =>
    listFiles(`${root}${input}`),
  ).pipe(Effect.map((groups) => groups.flat().sort()))
  const hash = createHash("sha256")
  for (const file of files) {
    hash.update(file.slice(root.length))
    hash.update("\0")
    hash.update(yield* fs.readFile(file))
    hash.update("\0")
  }
  const version = hash.digest("hex").slice(0, 16)
  return `export default ${JSON.stringify(version)}`
})

export interface OpenGraphMetadataPluginOptions {
  /**
   * Astro's resolved `cacheDir`, where the content layer writes
   * `data-store.json` during a build. Passed in from `astro.config.ts` rather
   * than hardcoded: the default is `node_modules/.astro/`, but the config
   * relocates it so CI can cache it, and a stale hardcoded path fails only on
   * a clean checkout.
   */
  readonly cacheDir: URL
}

export const openGraphMetadataPlugin = (
  options: OpenGraphMetadataPluginOptions,
): Plugin => ({
  name: "open-graph-metadata",
  resolveId(id) {
    if (id === moduleId) return resolvedModuleId
    if (id === rendererVersionModuleId) return resolvedRendererVersionModuleId
    return undefined
  },
  async load(id) {
    if (id === resolvedRendererVersionModuleId) {
      return Effect.runPromise(
        loadRendererVersion().pipe(Effect.provide(NodeFileSystem.layer)),
      )
    }
    if (id !== resolvedModuleId) return undefined
    // Dev keeps its own copy under `.astro/` and never consults `cacheDir`.
    const storeUrl =
      this.environment.mode === "build"
        ? new URL("data-store.json", options.cacheDir)
        : new URL("../../../.astro/data-store.json", import.meta.url)
    const storePath = fileURLToPath(storeUrl)
    this.addWatchFile(storePath)
    return Effect.runPromise(
      loadMetadata(storePath).pipe(Effect.provide(NodeFileSystem.layer)),
    )
  },
})

